   *  for a bad share or a to-date before the from-date. The dates (yyyy-mm-dd) are blank for none. */
  async addMember(
    sheet: string,
    poolId: number,
    member: { personId: number } | { poolId: number },
    share: string,
    from = '',
    to = '',
